-- BASE: model.mint_content_artifact sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e (run 3d736602). RESULT SETS: base; minted (4 rows); readback (retained = 1, four times).
SET NOCOUNT ON;
